declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/LeadService.php';require __DIR__.'/../src/FlowService.php';$db=db();if($db->getAttribute(PDO::ATTR_DRIVER_NAME)!=='mysql')throw new RuntimeException('MySQL obrigatório.');$admin=$db->query("SELECT id,name,email,role FROM users WHERE role='admin' LIMIT 1")->fetch();$broker=$db->query("SELECT id,name,email,role FROM users WHERE role='broker' LIMIT 1")->fetch();$flow=$db->query("SELECT * FROM automation_flows WHERE name='Interesse em compra'")->fetch();$svc=new FlowService($db,new LeadService($db));$conversation='mysql-flow-'.bin2hex(random_bytes(4));
$r=$svc->message($flow['id'],$conversation,'Olá',true,$admin);assert(count($r['replies'])===2);$svc->message($flow['id'],$conversation,'Cliente Builder',true,$admin);$svc->message($flow['id'],$conversation,'11999990000',true,$admin);$svc->message($flow['id'],$conversation,'Centro',true,$admin);$r=$svc->message($flow['id'],$conversation,'650000',true,$admin);assert($r['lead_id']);$q=$db->prepare('SELECT property_interest FROM opportunities WHERE id=?');$q->execute([$r['lead_id']]);assert($q->fetchColumn()==='TESTE LOCAL DO SIMULADOR');
$published=$flow['published_version_id'];$graph=json_decode($db->query("SELECT graph FROM flow_versions WHERE id='$published'")->fetchColumn(),true);$saved=$svc->save($flow['id'],$flow['name'],$graph,$admin);assert($saved['version_id']!==$published);$q=$db->prepare('SELECT published_version_id FROM automation_flows WHERE id=?');$q->execute([$flow['id']]);assert($q->fetchColumn()===$published);try{$svc->save(null,'Sem permissão',$graph,$broker);assert(false);}catch(AuthorizationException $e){}
echo "OK MySQL: versão publicada preservada, conversa retomada, perguntas e criação integrada de lead.\n";
